using System.Xml.Linq;

namespace ExternGenerator.Analysis;

/// <summary>
/// Parses XML documentation files generated by the C# compiler.
/// </summary>
public class XmlDocParser
{
    private readonly Dictionary<string, MemberDoc> _members = new();

    /// <summary>
    /// Loads and parses an XML documentation file.
    /// </summary>
    public void Load(string xmlPath)
    {
        if (!File.Exists(xmlPath))
            return;

        try
        {
            var doc = XDocument.Load(xmlPath);
            var members = doc.Root?.Element("members")?.Elements("member");

            if (members == null)
                return;

            foreach (var member in members)
            {
                string? name = member.Attribute("name")?.Value;
                if (string.IsNullOrEmpty(name))
                    continue;

                var memberDoc = new MemberDoc
                {
                    Name = name,
                    Summary = CleanDocText(member.Element("summary")?.Value),
                    Returns = CleanDocText(member.Element("returns")?.Value),
                    Remarks = CleanDocText(member.Element("remarks")?.Value),
                    Value = CleanDocText(member.Element("value")?.Value),
                };

                // Parse parameters
                foreach (var param in member.Elements("param"))
                {
                    string? paramName = param.Attribute("name")?.Value;
                    if (!string.IsNullOrEmpty(paramName))
                    {
                        memberDoc.Parameters[paramName] = CleanDocText(param.Value);
                    }
                }

                // Parse type parameters
                foreach (var typeParam in member.Elements("typeparam"))
                {
                    string? paramName = typeParam.Attribute("name")?.Value;
                    if (!string.IsNullOrEmpty(paramName))
                    {
                        memberDoc.TypeParameters[paramName] = CleanDocText(typeParam.Value);
                    }
                }

                // Parse exceptions
                foreach (var exception in member.Elements("exception"))
                {
                    string? exType = exception.Attribute("cref")?.Value;
                    if (!string.IsNullOrEmpty(exType))
                    {
                        memberDoc.Exceptions[exType] = CleanDocText(exception.Value);
                    }
                }

                _members[name] = memberDoc;
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Warning: Failed to parse XML documentation: {ex.Message}");
        }
    }

    /// <summary>
    /// Gets documentation for a type.
    /// </summary>
    public MemberDoc? GetTypeDoc(string fullTypeName)
    {
        // Type documentation key format: T:Namespace.TypeName
        string key = $"T:{fullTypeName}";
        return _members.TryGetValue(key, out var doc) ? doc : null;
    }

    /// <summary>
    /// Gets documentation for a method.
    /// </summary>
    public MemberDoc? GetMethodDoc(string fullTypeName, string methodName, IEnumerable<string>? parameterTypes = null)
    {
        // Method documentation key format: M:Namespace.TypeName.MethodName(ParamType1,ParamType2)
        string key = $"M:{fullTypeName}.{methodName}";
        if (parameterTypes != null && parameterTypes.Any())
        {
            key += $"({string.Join(",", parameterTypes)})";
        }

        if (_members.TryGetValue(key, out var doc))
            return doc;

        // Try without parameters for overloaded methods
        key = $"M:{fullTypeName}.{methodName}";
        foreach (var kvp in _members)
        {
            if (kvp.Key.StartsWith(key))
                return kvp.Value;
        }

        return null;
    }

    /// <summary>
    /// Gets documentation for a constructor.
    /// </summary>
    public MemberDoc? GetConstructorDoc(string fullTypeName, IEnumerable<string>? parameterTypes = null)
    {
        // Constructor key format: M:Namespace.TypeName.#ctor(ParamType1,ParamType2)
        string key = $"M:{fullTypeName}.#ctor";
        if (parameterTypes != null && parameterTypes.Any())
        {
            key += $"({string.Join(",", parameterTypes)})";
        }

        if (_members.TryGetValue(key, out var doc))
            return doc;

        // Try without parameters
        key = $"M:{fullTypeName}.#ctor";
        foreach (var kvp in _members)
        {
            if (kvp.Key.StartsWith(key))
                return kvp.Value;
        }

        return null;
    }

    /// <summary>
    /// Gets documentation for a property.
    /// </summary>
    public MemberDoc? GetPropertyDoc(string fullTypeName, string propertyName)
    {
        // Property key format: P:Namespace.TypeName.PropertyName
        string key = $"P:{fullTypeName}.{propertyName}";
        return _members.TryGetValue(key, out var doc) ? doc : null;
    }

    /// <summary>
    /// Gets documentation for a field.
    /// </summary>
    public MemberDoc? GetFieldDoc(string fullTypeName, string fieldName)
    {
        // Field key format: F:Namespace.TypeName.FieldName
        string key = $"F:{fullTypeName}.{fieldName}";
        return _members.TryGetValue(key, out var doc) ? doc : null;
    }

    /// <summary>
    /// Gets documentation for an event.
    /// </summary>
    public MemberDoc? GetEventDoc(string fullTypeName, string eventName)
    {
        // Event key format: E:Namespace.TypeName.EventName
        string key = $"E:{fullTypeName}.{eventName}";
        return _members.TryGetValue(key, out var doc) ? doc : null;
    }

    /// <summary>
    /// Cleans up documentation text by removing excess whitespace.
    /// </summary>
    private static string? CleanDocText(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return null;

        // Normalize whitespace
        var lines = text.Split('\n')
            .Select(l => l.Trim())
            .Where(l => !string.IsNullOrEmpty(l));

        return string.Join(" ", lines);
    }
}

/// <summary>
/// Documentation for a single member (type, method, property, etc.).
/// </summary>
public class MemberDoc
{
    public string Name { get; set; } = "";
    public string? Summary { get; set; }
    public string? Returns { get; set; }
    public string? Remarks { get; set; }
    public string? Value { get; set; }
    public Dictionary<string, string> Parameters { get; } = new();
    public Dictionary<string, string> TypeParameters { get; } = new();
    public Dictionary<string, string> Exceptions { get; } = new();

    /// <summary>
    /// Formats the documentation as a Haxe doc comment.
    /// </summary>
    public string? ToHaxeDocComment(string indent = "\t")
    {
        var parts = new List<string>();

        if (!string.IsNullOrEmpty(Summary))
            parts.Add(Summary);

        if (!string.IsNullOrEmpty(Remarks))
            parts.Add(Remarks);

        if (TypeParameters.Count > 0)
        {
            foreach (var kvp in TypeParameters)
            {
                parts.Add($"@param {kvp.Key} {kvp.Value}");
            }
        }

        if (Parameters.Count > 0)
        {
            foreach (var kvp in Parameters)
            {
                parts.Add($"@param {kvp.Key} {kvp.Value}");
            }
        }

        if (!string.IsNullOrEmpty(Returns))
            parts.Add($"@return {Returns}");

        if (parts.Count == 0)
            return null;

        // Format as Haxe doc comment
        if (parts.Count == 1 && !parts[0].Contains('\n'))
        {
            return $"{indent}/** {parts[0]} */";
        }

        var sb = new System.Text.StringBuilder();
        sb.AppendLine($"{indent}/**");
        foreach (var part in parts)
        {
            foreach (var line in WrapText(part, 80))
            {
                sb.AppendLine($"{indent} * {line}");
            }
        }
        sb.Append($"{indent} */");
        return sb.ToString();
    }

    /// <summary>
    /// Wraps text to a maximum line length.
    /// </summary>
    private static IEnumerable<string> WrapText(string text, int maxLength)
    {
        var words = text.Split(' ');
        var currentLine = new System.Text.StringBuilder();

        foreach (var word in words)
        {
            if (currentLine.Length + word.Length + 1 > maxLength && currentLine.Length > 0)
            {
                yield return currentLine.ToString();
                currentLine.Clear();
            }

            if (currentLine.Length > 0)
                currentLine.Append(' ');
            currentLine.Append(word);
        }

        if (currentLine.Length > 0)
            yield return currentLine.ToString();
    }
}
